package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.InformationRuntime;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class DifferentialReceiverBlock extends PassiveDirectionalSignalBlock{public DifferentialReceiverBlock(Properties p){super(p);}@Override public MapCodec<DifferentialReceiverBlock> codec(){return RedstoneEngineering.DIFFERENTIAL_RECEIVER_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){BlockPos in=inputPos(p,s);return InformationRuntime.valid(l,"diff",in)&&InformationRuntime.quality(l,"diff",in)>0&&InformationRuntime.value(l,"diff",in)!=0?15:0;}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){BlockPos in=inputPos(p,s);pl.displayClientMessage(Component.literal("Differential RX bit="+InformationRuntime.value(l,"diff",in)+" quality="+InformationRuntime.quality(l,"diff",in)+"%"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}